import { createServer } from "node:http";
import { createHash as createHash4 } from "node:crypto";

// shared/html.mjs
function scriptContents(html) {
  return [...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script\b[^>]*>/gi)].map(
    (match) => match[1]
  );
}

// server/preview.ts
